const body = $json.body || $json;
const workflow = body.workflow || {};
const grafanaClient = body.grafana_client || {};

const allowedPaths = new Set([
  '/platform/service-health',
  '/grafana/queue-backlog',
  '/grafana/queue-trend',
  '/grafana/throughput',
  '/grafana/http-health',
  '/grafana/java-errors',
  '/grafana/trace-metrics',
  '/grafana/logs',
  '/grafana/emqx',
  '/grafana/emqx/dropped-trend',
  '/grafana/emqx/connection-trend',
  '/grafana/k8s',
  '/grafana/k8s/resources',
  '/grafana/redis',
  '/grafana/mongodb',
  '/grafana/mysql',
  '/grafana/linux'
]);

const allowedParamsByPath = {
  '/platform/service-health': [],
  '/grafana/queue-backlog': ['namespace', 'topk', 'threshold'],
  '/grafana/queue-trend': ['namespace', 'queue', 'start', 'end', 'step'],
  '/grafana/throughput': ['queue'],
  '/grafana/http-health': ['project', 'window'],
  '/grafana/java-errors': ['window'],
  '/grafana/trace-metrics': ['window'],
  '/grafana/logs': ['service', 'level', 'hours_back', 'limit'],
  '/grafana/emqx': [],
  '/grafana/emqx/dropped-trend': ['start', 'end', 'step'],
  '/grafana/emqx/connection-trend': ['start', 'end', 'step'],
  '/grafana/k8s': [],
  '/grafana/k8s/resources': ['namespace', 'service', 'pod'],
  '/grafana/redis': [],
  '/grafana/mongodb': [],
  '/grafana/mysql': [],
  '/grafana/linux': []
};

const method = String(workflow.method || 'GET').toUpperCase();
const path = String(workflow.path || '');
const baseUrl = String(grafanaClient.base_url || 'http://127.0.0.1:5050').replace(/\/+$/, '');

if (method !== 'GET') {
  throw new Error(`Rejected non-read Grafana method: ${method}`);
}

if (!allowedPaths.has(path)) {
  throw new Error(`Rejected unapproved Grafana path: ${path}`);
}

const allowedParams = new Set(allowedParamsByPath[path] || []);
const rawParams = workflow.params || {};
const safeParams = {};
for (const [key, value] of Object.entries(rawParams)) {
  if (allowedParams.has(key) && value !== null && value !== undefined && value !== '') {
    safeParams[key] = String(value);
  }
}

const query = Object.entries(safeParams)
  .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
  .join('&');
const url = `${baseUrl}${path}${query ? `?${query}` : ''}`;

return [{
  json: {
    ...body,
    request: {
      method,
      url,
      path,
      params: safeParams,
      tool: workflow.tool,
      workflow_id: workflow.workflow_id
    },
    gateway_audit: {
      actor: 'n8n-grafana-ops-gateway',
      mutating: false,
      credentials: 'redacted',
      allowed_path: path,
      filtered_params: safeParams
    }
  }
}];

const evidence = $json;
const request = $('Validate Grafana Request').first().json.request;
const gatewayAudit = $('Validate Grafana Request').first().json.gateway_audit;
const workflow = $('Validate Grafana Request').first().json.workflow || {};
const kpiRules = $('Validate Grafana Request').first().json.kpi_rules || [];
const error = evidence.error || evidence.message && String(evidence.message).toLowerCase().includes('error') ? evidence : null;

if (error) {
  return [{
    json: {
      response: `Grafana workflow ${workflow.tool || request.workflow_id} failed before evidence was collected.`,
      evidence: {
        source: 'n8n_grafana_gateway',
        status: 'workflow_error',
        request: {
          method: request.method,
          path: request.path,
          url: request.url,
          params: request.params
        },
        error
      },
      steps: [
        {
          thought: 'n8n validated the approved IOA v3 Grafana workflow request.',
          action: 'validate_grafana_request',
          output: gatewayAudit
        },
        {
          thought: 'n8n attempted to call the approved Grafana Dashboard Client endpoint, but the call failed.',
          action: `${request.method} ${request.path}`,
          output: {
            source: 'grafana_dashboard_client',
            status: 'failed',
            error
          }
        }
      ],
      token_usage: null
    }
  }];
}

const level = evidence.level || evidence.overall_verdict || evidence.status || 'unknown';
const response = [
  `Grafana workflow ${workflow.tool || request.workflow_id} completed.`,
  `Endpoint: ${request.method} ${request.path}.`,
  `Level: ${level}.`
].join(' ');

return [{
  json: {
    response,
    evidence: {
      source: 'grafana_dashboard_client',
      request: {
        method: request.method,
        path: request.path,
        params: request.params
      },
      level,
      body: evidence,
      kpi_rules: kpiRules
    },
    steps: [
      {
        thought: 'n8n validated the approved IOA v3 Grafana workflow request.',
        action: 'validate_grafana_request',
        output: gatewayAudit
      },
      {
        thought: 'n8n called the approved Grafana Dashboard Client endpoint.',
        action: `${request.method} ${request.path}`,
        output: {
          source: 'grafana_dashboard_client',
          level,
          params: request.params
        }
      }
    ],
    token_usage: null
  }
}];
